/**
 * Font registry shared by the browser renderer and the PDF renderer.
 * Every face listed here exists as `src/assets/fonts/<file>.ttf` (PDF) and
 * `public/fonts/<file>.woff2` (browser) — generated by `scripts/fetch-fonts.mjs`.
 */
export type FontId =
  | 'cormorant'
  | 'playfair'
  | 'inter'
  | 'manrope'
  | 'baskerville'
  | 'dmserif'
  | 'montserrat'
  | 'greatvibes'
  | 'caveat'
  | 'specialelite'
  | 'fredoka'
  | 'josefin'
  | 'garamond'
  | 'bodoni'
  | 'pinyon'
  | 'fraunces'
  | 'jost';

export interface FontFace {
  weight: number;
  italic: boolean;
  file: string;
}

export interface FontDef {
  id: FontId;
  label: string;
  /** CSS font-family name used for @font-face. */
  family: string;
  category: 'serif' | 'sans' | 'script' | 'display' | 'mono';
  fallback: string;
  faces: FontFace[];
}

const f = (file: string, weight: number, italic = false): FontFace => ({ file, weight, italic });

