export const FONT_LIST: FontDef[] = Object.values(FONTS);

/** Pick the closest available face for a requested weight/style. */
export function resolveFace(fontId: FontId, weight: number, italic: boolean): FontFace {
  const def = FONTS[fontId] ?? FONTS.inter;
  const sameStyle = def.faces.filter((x) => x.italic === italic);
  const pool = sameStyle.length ? sameStyle : def.faces;
  return pool.reduce((best, face) =>
    Math.abs(face.weight - weight) < Math.abs(best.weight - weight) ? face : best,
  );
}

export function cssFontStack(fontId: FontId): string {
  const def = FONTS[fontId] ?? FONTS.inter;
  return `"${def.family}", ${def.fallback}`;
}

export function availableWeights(fontId: FontId): number[] {
  const def = FONTS[fontId] ?? FONTS.inter;
  return [...new Set(def.faces.map((x) => x.weight))].sort((a, b) => a - b);
}

export function hasItalic(fontId: FontId): boolean {
  return (FONTS[fontId] ?? FONTS.inter).faces.some((x) => x.italic);
}

/** Generates @font-face CSS for all registered faces. */
export function fontFaceCss(basePath = '/fonts'): string {
  return FONT_LIST.flatMap((def) =>
    def.faces.map(
      (face) =>
        `@font-face{font-family:"${def.family}";src:url(${basePath}/${face.file}.woff2) format("woff2");font-weight:${face.weight};font-style:${face.italic ? 'italic' : 'normal'};font-display:swap;}`,
    ),
  ).join('\n');
}
